style.css:
/* PINTEREST DARK BURGUNDY */

html, body {
    background-color: #160D18 !important;
}

/* Fondos principales */
main,
[role="main"] {
    background-color: #160D18 !important;
}

/* Buscador */
input {
    background-color: #241322 !important;
    color: #F0DDE5 !important;
    border: 1px solid #581C35 !important;
}

/* Botones */
button {
    border-color: #792D49 !important;
}

/* Paneles y menús */
[role="dialog"],
[role="menu"] {
    background-color: #241322 !important;
    color: #F0DDE5 !important;
}
